/* The built-in underwriting tool (app/uwtool/, docs/proposals/monal-builtin-and-rename.md, PR 3). It is generated by
 * tools/uwtool-import.mjs and must not be edited by hand. Checks:
 *   1. every file under app/uwtool/ is exactly what IMPORT-MANIFEST.json says (a hand edit, a stray file or a missing one fails);
 *   2. nothing there asks for another host: a static scan of every text file for http(s) addresses outside a short list
 *      of namespace names and library comments (the browser flow tests/e2e/uwtool-flow.mjs counts real requests);
 *   3. the content policy is in the service worker's header AND in the page's <meta>, and is strict (no eval, no inline script,
 *      no outside connection or font);
 *   4. a blank cap rate stays blank: the tool's own blank model has none, and its finance check asks for one rather than
 *      using a made-up value;
 *   5. the licence file says all rights reserved; the three licence notes say the MIT licence does not cover the folder.
 * Each check is a function with a mutation test below it: allow an outside host, drop the policy, change a file. */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const DIR = path.join(ROOT, 'app/uwtool');
const sha = (b) => crypto.createHash('sha256').update(b).digest('hex');
const read = (p) => fs.readFileSync(path.join(ROOT, p), 'utf8');
const walk = (d, base = d) => fs.readdirSync(d, { withFileTypes: true }).flatMap((e) => (e.isDirectory() ? walk(path.join(d, e.name), base) : [path.relative(base, path.join(d, e.name)).split(path.sep).join('/')]));
const isText = (b) => !b.includes(0);

/** Files that differ from the manifest: changed, extra (not in it) or missing. @param {Record<string, Buffer>} files @param {any} manifest */
export function manifestProblems(files, manifest) {
  const out = [];
  for (const [rel, m] of Object.entries(manifest.files)) {
    if (!(rel in files)) out.push(`missing: ${rel}`);
    else if (sha(files[rel]) !== m.out || files[rel].length !== m.bytes) out.push(`changed: ${rel}`);
  }
  for (const rel of Object.keys(files)) if (rel !== 'IMPORT-MANIFEST.json' && !(rel in manifest.files)) out.push(`extra: ${rel}`);
  return out;
}

// names, not requests: XML namespaces and the comments of the libraries (pdf.js, JSZip, SheetJS); the browser flow proves no request is made
export const HOSTS_OK = [
  'www.w3.org', 'schemas.openxmlformats.org', 'schemas.microsoft.com', 'sheetjs.openxmlformats.org', 'purl.oclc.org', 'purl.org',
  'docs.oasis-open.org', 'openoffice.org', 'ns.adobe.com', 'www.xfa.org', 'macVmlSchemaUri',                           // namespaces in the readers
  'sheetjs.com', 'github.com', 'raw.github.com', 'stuk.github.io', 'stuartk.com', 'www.apache.org',                   // licence and credit comments
];
/** http(s) hosts in any text file that are not on the list: ['file: host']. */
export function outsideHosts(files, ok = HOSTS_OK) {
  const out = [];
  for (const [rel, b] of Object.entries(files)) {
    if (!isText(b)) continue;
    for (const m of b.toString('utf8').matchAll(/(?:https?:)?\/\/([A-Za-z0-9._-]+\.[A-Za-z]{2,}|[A-Za-z0-9._-]+\/)/g)) {
      const host = m[1].replace(/\/$/, '');
      if (/^https?:/.test(m[0]) || /^\/\/[a-z0-9.-]+\.(com|net|org|io|dev)\b/i.test(m[0])) if (!ok.includes(host)) out.push(`${rel}: ${host}`);
    }
  }
  return out;
}

/** Faults in a policy string. */
export function policyFaults(csp, { header = false } = {}) {
  const f = []; const d = Object.fromEntries(csp.split(';').map((x) => x.trim()).filter(Boolean).map((x) => { const [k, ...v] = x.split(/\s+/); return [k, v.join(' ')]; }));
  if (d['script-src'] !== "'self'") f.push(`script-src is ${d['script-src']}`);
  if (/unsafe-eval|unsafe-inline/.test(d['script-src'] || '')) f.push('script-src allows eval or inline');
  for (const k of ['connect-src', 'font-src', 'img-src', 'worker-src', 'style-src']) if (!d[k]) f.push(`no ${k}`);
  if (/https?:|\*/.test(csp)) f.push('names an outside host or a wildcard');
  if (d['connect-src'] !== "'self' blob: data:") f.push(`connect-src is ${d['connect-src']}`);
  if (d['object-src'] !== "'none'") f.push('object-src not none');
  if (header && d['frame-ancestors'] !== "'self'") f.push('no frame-ancestors self');
  return f;
}
const swPolicy = () => { const sw = read('sw.js'); const m = sw.match(/const UW_CSP = \[([\s\S]*?)\]\.join\('; '\);/); return [...m[1].matchAll(/"([^"]+)"/g)].map((x) => x[1]).join('; '); };
const metaPolicy = (html) => (html.match(/<meta http-equiv="Content-Security-Policy" content="([^"]+)"/) || [])[1] || '';

const files = () => Object.fromEntries(walk(DIR).map((r) => [r, fs.readFileSync(path.join(DIR, r))]));
const manifest = () => JSON.parse(read('app/uwtool/IMPORT-MANIFEST.json'));

test('the shipped folder is exactly what the import manifest says', () => {
  assert.deepEqual(manifestProblems(files(), manifest()), []);
  const m = manifest();
  assert.ok(Object.keys(m.files).length >= 70 && m.package.fingerprint.length === 64, 'the manifest lists the files and the package fingerprint');
  assert.ok(m.edits.length >= 40 && m.edits.every((e) => e.id && e.category), 'every edit has an id and a category');
  assert.equal(JSON.stringify(m).includes('find'), false, 'the manifest holds no find strings');
});
test('MUTATION: a changed, an extra and a missing file are all found', () => {
  const f = files(); const m = manifest();
  assert.deepEqual(manifestProblems({ ...f, 'editor.js': Buffer.concat([f['editor.js'], Buffer.from(' ')]) }, m), ['changed: editor.js']);
  assert.deepEqual(manifestProblems({ ...f, 'extra.js': Buffer.from('x') }, m), ['extra: extra.js']);
  const { 'model.js': _gone, ...rest } = f;
  assert.deepEqual(manifestProblems(rest, m), ['missing: model.js']);
});

test('nothing in the folder names another host', () => {
  assert.deepEqual(outsideHosts(files()), []);
});
test('MUTATION: an outside host in a script, a stylesheet or the page is found', () => {
  const f = files();
  const add = (name, text) => ({ ...f, [name]: Buffer.concat([f[name], Buffer.from(text)]) });
  assert.deepEqual(outsideHosts(add('editor.js', "\nfetch('https://api.example.test/x');")), ['editor.js: api.example.test']);
  assert.deepEqual(outsideHosts(add('plex-fonts.css', '\n@import url(https://fonts.example.test/css);')), ['plex-fonts.css: fonts.example.test']);
  assert.deepEqual(outsideHosts(add('index.html', '<script src="//cdn.example.com/a.js"></script>')), ['index.html: cdn.example.com']);
});
test('the tool asks for no font, script, AI or lookup address of its own', () => {
  const all = Object.values(files()).filter(isText).map((b) => b.toString('utf8')).join('\n');
  assert.doesNotMatch(all, /fonts\.googleapis|fonts\.gstatic|jsdelivr|unpkg|cdnjs|api\.anthropic\.com/);
  assert.doesNotMatch(all, /fetch\(['"`]\/api\//, 'no call to an /api/ route');
  assert.doesNotMatch(all, /localStorage\.setItem\('uw_key'/, 'no API key written to storage');
  assert.doesNotMatch(files()['index.html'].toString(), /<script(?![^>]*\bsrc=)[^>]*>/, 'no inline script in the page');
  assert.doesNotMatch(all, /\son(?:change|click|input|load|error)="/, 'no inline event handler');
  assert.match(all, /isEvalSupported:false/, 'pdf.js eval is off');
  assert.doesNotMatch(files()['editor.js'].toString(), /getDocument\(\{data:bytes\.slice\(\)\}\)/, 'no pdf.js call with eval left on');
});

test('the policy is in the service worker header and in the page, and it is strict', () => {
  const header = swPolicy();
  assert.deepEqual(policyFaults(header, { header: true }), []);
  const meta = metaPolicy(files()['index.html'].toString());
  assert.ok(meta, 'the page carries the policy as a <meta>');
  assert.deepEqual(policyFaults(meta), []);
  // the meta is the header without frame-ancestors (a meta cannot set it)
  assert.equal(meta, header.split('; ').filter((x) => !x.startsWith('frame-ancestors')).join('; '));
  const sw = read('sw.js');
  assert.match(sw, /UW_TOOL_ROOT\(\)\)\) \{ e\.respondWith\(uwToolFile\(e\.request\)\)/, 'sw.js routes app/uwtool/');
  assert.match(sw, /zlatura-uwtool-\$\{VERSION\}/, 'its own bucket, named for the release');
  assert.match(sw, /k !== UW_TOOL_CACHE/, 'activate keeps the current bucket and drops older ones');
  const assets = sw.slice(sw.indexOf('const ASSETS'), sw.indexOf('];'));
  assert.doesNotMatch(assets, /app\/uwtool\//, 'the tool is not in the install set');
});
test('MUTATION: a dropped or loosened policy is found', () => {
  const header = swPolicy();
  assert.deepEqual(policyFaults('', { header: true }), ['script-src is undefined', 'no connect-src', 'no font-src', 'no img-src', 'no worker-src', 'no style-src', 'connect-src is undefined', 'object-src not none', 'no frame-ancestors self']);
  assert.ok(policyFaults(header.replace("script-src 'self'", "script-src 'self' 'unsafe-eval'")).length >= 1);
  assert.ok(policyFaults(header.replace("font-src 'self'", "font-src 'self' https://fonts.gstatic.com")).includes('names an outside host or a wildcard'));
  assert.ok(policyFaults(header.replace("connect-src 'self' blob: data:", "connect-src *")).length >= 1);
  assert.deepEqual(policyFaults(header.replace("; frame-ancestors 'self'", ''), { header: true }), ['no frame-ancestors self']);
  assert.equal(metaPolicy('<html><head></head>'), '');
});

test('a blank cap rate stays blank: no preset, no zero; the tool asks for one', () => {
  const ctx = { console }; ctx.window = ctx; ctx.globalThis = ctx; vm.createContext(ctx);
  for (const f of ['model.js', 'finance.js']) vm.runInContext(fs.readFileSync(path.join(DIR, f), 'utf8'), ctx, { filename: f });
  const m = ctx.UW.blank();
  assert.strictEqual(m.cap, '', 'the model has no preset cap rate');
  assert.ok(ctx.UWFinance.calculate(m).errors.includes('Enter the exit cap rate.'), 'the finance check asks for the exit cap rate');
  const html = files()['index.html'].toString();
  for (const id of ['f_c1', 'f_c2', 'f_c3']) {
    const tag = html.match(new RegExp(`<input id="${id}"[^>]*>`))[0];
    assert.doesNotMatch(tag, /\bvalue=/, `${id} has no value`);
    assert.match(tag, /placeholder="enter a cap rate"/);
  }
  const editor = files()['editor.js'].toString();
  assert.doesNotMatch(editor, /\.0725|\.0675|\|\|\.07\b/, 'no cap rate preset left in the editor');
  assert.match(editor, /const capOf=id=>/, 'a blank form field is saved as blank, not 0');
});

test('the licence is all rights reserved, and the root licence, readme and third-party list say MIT does not cover the folder', () => {
  const lic = read('app/uwtool/LICENSE');
  assert.match(lic, /Copyright \(c\) 2026 Kyle Alexander De Melo\. ALL RIGHTS RESERVED/);
  assert.match(lic, /MIT licence of\s+the rest of this repository[\s\S]*DOES NOT APPLY/);
  for (const f of ['LICENSE', 'README.md', 'THIRD_PARTY.md']) assert.match(read(f), /app\/uwtool\/[\s\S]{0,300}all rights reserved|all rights reserved[\s\S]{0,300}app\/uwtool\//i, `${f} names the exception`);
  assert.match(read('app/uwtool/README.md'), /generated[\s\S]*do not edit/i);
});
